package scanners

import (
	"slices"
	"strings"
	"testing"
)

// Import formats for infrastructure, TLS, container and runtime tools.
//
// Fixtures generated by running the tool's official image on 2026-11-19
// against a local nginx test container (alpine 3.22, self-signed
// certificate, TLS 1.0-1.3 and all OpenSSL ciphers enabled) on an internal
// Docker network without internet access:
//   - nmap.xml: instrumentisto/nmap:latest (Nmap 7.98), `-sV -p 22,80,443
//     --script ssl-enum-ciphers,ssl-cert,http-server-header,http-methods,
//     ssl-dh-params,sslv2,http-vuln-cve2011-3192,http-enum -oX`; verbatim
//     (the http-vuln-cve2011-3192 result against nginx is the script's own
//     false positive, kept as reported).
//   - testssl.json: drwetter/testssl.sh:latest (3.2.5), `--jsonfile`;
//     trimmed to 15 of 205 entries, re-indented.
//   - testssl-pretty.json: the same image, `-p -U -S --jsonfile-pretty`;
//     each section trimmed to 5 entries.
//   - sslyze.json: nablac0d3/sslyze:latest (6.3.1), `--json_out`; rejected
//     cipher suites, most accepted ones and some trust-store results
//     removed to keep it small.
//   - sslscan.xml: sslscan 2.1.6 (Alpine 3.22 package; the project
//     publishes no official image), `--xml`; most strong cipher lines and
//     the key-exchange group lines removed.
//   - dockle.json: goodwithtech/dockle:latest (0.4.15), `-f json --input`
//     on a locally built image (ADD, ENV DB_PASSWORD, setuid file, root);
//     verbatim.
//
// Fixtures built from the published format (no real export available):
//   - nmap-vulners.xml: the vulners script's XML structure
//     (https://github.com/vulnersCom/nmap-vulners, vulners.nse) and the vulns
//     library's NOT VULNERABLE table; the script needs internet access.
//   - clair.json: Clair v4 VulnerabilityReport
//     (https://quay.github.io/clair/reference/api.html).
//   - harbor.json: Harbor's additions/vulnerabilities response, report MIME
//     type version 1.1 (https://github.com/goharbor/pluggable-scanner-spec).
//   - trivy-k8s.json: `trivy k8s --format json --report all`
//     (pkg/k8s/report/report.go in aquasecurity/trivy: ClusterName,
//     Resources[] with Namespace, Kind, Name, Results).
//   - wazuh-alerts.jsonl: vulnerability-detector alerts of Wazuh 4.x
//     alerts.json (https://documentation.wazuh.com/current/user-manual/capabilities/vulnerability-detection/).
//   - wazuh-states.json: an Indexer search response over
//     wazuh-states-vulnerabilities-* (Wazuh 4.8+ index template).
//   - falco.jsonl: Falco json_output alerts (https://falco.org/docs/outputs/formatting/).
//   - tetragon.jsonl: Tetragon JSON export events (api/v1/tetragon/events.proto
//     and tetragon.proto: process_exec, process_kprobe, process_exit).
//   - tracee.jsonl: Tracee JSON events (types/trace/trace.go) with signature
//     metadata of TRC-101 and TRC-102.
// Falco, Tetragon and Tracee need kernel privileges (eBPF or a kernel
// module) and were not run.

func TestImportNmap(t *testing.T) {
	fs := checkImport(t, "nmap.xml", "nmap", "import-other-nmap", 6)
	if p := fs[0]; p.Severity != "info" || p.FilePath != "a3-g2-target:80/tcp" || !strings.Contains(p.Title, "nginx 1.28.3") ||
		!strings.Contains(p.Description, "http-server-header") {
		t.Errorf("open port: %+v", p)
	}
	if v := fs[1]; v.RuleID != "http-vuln-cve2011-3192" || v.CVE != "CVE-2011-3192" || v.Severity != "high" || v.Title != "Apache byterange filter DoS" {
		t.Errorf("vuln script: %+v", v)
	}
	if p := fs[3]; p.Severity != "medium" || !strings.Contains(p.Title, "TLSv1.0, TLSv1.1") || !slices.Equal(p.CWE, []string{"CWE-327"}) {
		t.Errorf("protocols: %+v", p)
	}
	if c := fs[4]; c.Severity != "high" || !strings.Contains(c.Description, "Anonymous key exchange") {
		t.Errorf("ciphers: %+v", c)
	}
	// Closed ports, NOT VULNERABLE results and filtered ports are not findings.
	vs := checkImport(t, "nmap-vulners.xml", "nmap", "import-other-nmap", 4)
	if v := vs[1]; v.CVE != "CVE-2023-38408" || v.Severity != "critical" || v.CVSS == nil || *v.CVSS != 9.8 || v.FilePath != "192.0.2.20:22/tcp" {
		t.Errorf("vulners: %+v", v)
	}
	if vs[2].Severity != "medium" || vs[3].RuleID != "nmap-open-port" {
		t.Errorf("vulners: %+v", vs[2:])
	}
}

func TestImportTLSScanners(t *testing.T) {
	fs := checkImport(t, "testssl.json", "testssl", "import-other-testssl", 11)
	if f := fs[2]; f.RuleID != "testssl.cipherlist_aNULL" || f.Severity != "critical" || f.FilePath != "a3-g2-target:443" || !slices.Equal(f.CWE, []string{"CWE-327"}) {
		t.Errorf("aNULL: %+v", f)
	}
	for _, f := range fs {
		if f.RuleID == "testssl.engine_problem" || f.RuleID == "testssl.service" || f.RuleID == "testssl.SSLv2" {
			t.Errorf("WARN, INFO and OK entries are not findings: %+v", f)
		}
		if f.RuleID == "testssl.BEAST" && (f.CVE != "CVE-2011-3389" || f.Severity != "low") {
			t.Errorf("BEAST: %+v", f)
		}
	}
	pretty := checkImport(t, "testssl-pretty.json", "testssl", "import-other-testssl", 9)
	if pretty[0].RuleID != "testssl.BEAST" || pretty[0].FilePath != "a3-g2-target:443" {
		t.Errorf("pretty: %+v", pretty[0])
	}
	// The same check gives the same identity in both shapes.
	if fs[8].RuleID != "testssl.BEAST" || fs[8].Fingerprint != pretty[0].Fingerprint {
		t.Errorf("flat and pretty BEAST differ: %+v %+v", fs[8], pretty[0])
	}

	sy := checkImport(t, "sslyze.json", "sslyze", "import-other-sslyze", 4)
	if sy[0].RuleID != "sslyze.tls_1.0_supported" || sy[0].Severity != "medium" || sy[0].FilePath != "a3-g2-target:443" {
		t.Errorf("sslyze tls1.0: %+v", sy[0])
	}
	if a := sy[2]; a.Severity != "high" || !strings.Contains(a.Description, "TLS_ECDH_anon_WITH") {
		t.Errorf("sslyze anon: %+v", a)
	}
	if c := sy[3]; c.Severity != "high" || !slices.Equal(c.CWE, []string{"CWE-295"}) || !strings.Contains(c.Description, "subjectAltName") {
		t.Errorf("sslyze cert: %+v", c)
	}

	ss := checkImport(t, "sslscan.xml", "sslscan", "import-other-sslscan", 7)
	if ss[2].RuleID != "sslscan.cipher.AECDH-AES256-SHA" || ss[2].Severity != "high" || !strings.Contains(ss[2].Description, "TLSv1.0") {
		t.Errorf("sslscan anon: %+v", ss[2])
	}
	if ss[4].Severity != "low" || ss[6].RuleID != "sslscan.certificate.self-signed" {
		t.Errorf("sslscan: %+v", ss[4:])
	}
}

func TestImportContainerReports(t *testing.T) {
	raw := readImportFixture(t, "dockle.json")
	ds := checkImport(t, "dockle.json", "dockle", "import-container-dockle", 6)
	if d := ds[1]; d.RuleID != "CIS-DI-0010" || d.Severity != "high" || !slices.Equal(d.CWE, []string{"CWE-798"}) || d.Category != "container" {
		t.Errorf("dockle: %+v", d)
	}
	if ds[2].Severity != "medium" || ds[3].Severity != "info" {
		t.Errorf("dockle levels: %+v", ds[2:4])
	}
	// Dockle masks ENV values itself (the image's DB_PASSWORD is not in
	// the report); token-shaped values in alerts are redacted again.
	if strings.Contains(string(raw), "fixture-not-a-real-password") {
		t.Error("dockle: fixture contains the image's secret")
	}
	planted := []byte(strings.Replace(string(raw), "Last user should not be root", "token ghp_FixtureFixtureFixtureFixture0123", 1))
	if p, _ := ParseImport("import-container-dockle", "dockle", SanitizeImport("dockle", planted)); strings.Contains(p[2].Description, "ghp_Fixture") ||
		strings.Contains(string(SanitizeImport("dockle", planted)), "ghp_Fixture") {
		t.Error("dockle: token kept")
	}

	cl := checkImport(t, "clair.json", "clair", "import-container-clair", 2)
	if c := cl[0]; c.CVE != "CVE-2024-5535" || c.PackageName != "openssl" || c.PackageVersion != "3.0.11-1~deb12u1" || c.FixedVersion != "3.0.14-1~deb12u1" ||
		c.Severity != "high" || !strings.HasPrefix(c.FilePath, "sha256:") {
		t.Errorf("clair: %+v", c)
	}
	if cl[1].Severity != "info" {
		t.Errorf("negligible: %+v", cl[1])
	}

	hb := checkImport(t, "harbor.json", "harbor", "import-container-harbor", 2)
	if h := hb[0]; h.CVE != "CVE-2024-45337" || h.Severity != "critical" || h.CVSS == nil || *h.CVSS != 9.1 || h.CVSSVersion != "3.1" ||
		h.FixedVersion != "0.31.0" || !strings.HasPrefix(h.FilePath, "library/shop-api@sha256:") || !slices.Equal(h.CWE, []string{"CWE-285"}) ||
		!strings.Contains(h.Description, "Trivy v0.58.1") {
		t.Errorf("harbor: %+v", h)
	}
	// The bare report of the pluggable scanner API is accepted too.
	bare := []byte(`{"generated_at":"2026-01-01T00:00:00Z","artifact":{"repository":"lib/x","tag":"1"},"scanner":{"name":"Trivy"},"severity":"Low","vulnerabilities":[{"id":"CVE-2020-0001","package":"p","version":"1","severity":"Low"}]}`)
	if DetectImportFormat(bare) != "harbor" {
		t.Error("bare harbor report")
	}
	if b, err := ParseImport("import-container-harbor", "", bare); err != nil || len(b) != 1 || b[0].FilePath != "lib/x:1" {
		t.Errorf("bare: %v %+v", err, b)
	}

	raw = readImportFixture(t, "trivy-k8s.json")
	clean := SanitizeImport("trivy-k8s", raw)
	if strings.Contains(string(clean), "AKIAFIXTUREFIXTURE12") || !strings.Contains(string(clean), "runAsNonRoot") {
		t.Fatal("trivy-k8s: secret kept or other content lost")
	}
	tk := checkImport(t, "trivy-k8s.json", "trivy-k8s", "import-other-trivy", 3) // the PASS check is skipped
	if v := tk[0]; v.Category != "container" || v.FilePath != "shop/Deployment/web" || v.CVE != "CVE-2024-6119" || v.FixedVersion != "3.1.7-r0" ||
		!strings.Contains(v.Description, "nginx:1.25-alpine") || !strings.Contains(v.Description, "kind-pathos") {
		t.Errorf("k8s vulnerability: %+v", v)
	}
	if m := tk[1]; m.Category != "iac" || m.RuleID != "AVD-KSV-0012" || *m.StartLine != 132 {
		t.Errorf("k8s misconfiguration: %+v", m)
	}
	if s := tk[2]; s.Category != "secrets" || s.FilePath != "shop/ConfigMap/web-env" {
		t.Errorf("k8s secret: %+v", s)
	}
	loc, _ := LocateImport("import-other-trivy", "trivy-k8s", raw, tk[2].Fingerprint)
	if loc == nil || strings.Contains(string(loc.Raw), "AKIAFIXTURE") {
		t.Error("k8s secret located with its value")
	}
	// The ordinary Trivy report is not a Kubernetes report and vice versa.
	if DetectImportFormat(readImportFixture(t, "trivy.json")) != "trivy" {
		t.Error("trivy.json")
	}
	if DetectImportFormat([]byte(`{"SchemaVersion":2,"ClusterName":"c","Resources":[]}`)) != "trivy-k8s" {
		t.Error("empty k8s report")
	}
}

func TestImportWazuh(t *testing.T) {
	al := checkImport(t, "wazuh-alerts.jsonl", "wazuh", "import-other-wazuh", 2)
	if a := al[0]; a.Category != "sca" || a.CVE != "CVE-2021-22946" || a.PackageName != "curl" || a.PackageVersion != "7.68.0-1ubuntu2.6" ||
		a.Severity != "high" || a.CVSS == nil || *a.CVSS != 7.5 || a.FilePath != "web01 (192.0.2.31)" || !slices.Equal(a.CWE, []string{"CWE-319"}) {
		t.Errorf("alert: %+v", a)
	}
	// The sshd alert is not a vulnerability; the "solved" alert updates the
	// earlier finding instead of duplicating it.
	if b := al[1]; b.FilePath != "db01 (192.0.2.32)" || !strings.Contains(b.Description, "Later status: Solved") {
		t.Errorf("solved: %+v", b)
	}
	st := checkImport(t, "wazuh-states.json", "wazuh", "import-other-wazuh", 2)
	if s := st[0]; s.CVE != "CVE-2024-6387" || s.Severity != "high" || s.CVSS == nil || *s.CVSS != 8.1 || s.PackageName != "openssh-server" || s.FilePath != "bastion" {
		t.Errorf("state: %+v", s)
	}
	if st[1].Confidence != "low" || st[1].Severity != "info" {
		t.Errorf("under evaluation: %+v", st[1])
	}
	// Index documents as JSON lines are detected too.
	line := []byte(`{"agent":{"id":"1","name":"a"},"package":{"name":"p","version":"1"},"vulnerability":{"id":"CVE-2020-1111","severity":"Low"},"wazuh":{"schema":{"version":"1.0.0"}}}` + "\n")
	if DetectImportFormat(line) != "wazuh" {
		t.Error("state lines")
	}
	// Alerts without vulnerability-detector are not Wazuh vulnerability reports.
	if DetectImportFormat([]byte(`{"rule":{"id":"5710","groups":["sshd"]},"agent":{"id":"1"},"data":{}}`)) == "wazuh" {
		t.Error("ordinary alert detected")
	}
}

func TestImportRuntime(t *testing.T) {
	secrets := []string{"S3cretFixturePass", "AnotherFixtureSecret", "EnvFixtureSecret", "fixtureTokenValue123456", "CliFixtureToken"}
	for _, c := range []struct {
		file, format string
		n            int
	}{{"falco.jsonl", "falco", 3}, {"tetragon.jsonl", "tetragon", 2}, {"tracee.jsonl", "tracee", 2}} {
		raw := readImportFixture(t, c.file)
		fs := checkImport(t, c.file, c.format, "import-other-"+c.format, c.n)
		clean := SanitizeImport(c.format, raw)
		again, err := ParseImport("import-other-"+c.format, "", clean)
		if err != nil || len(again) != len(fs) {
			t.Fatalf("%s: sanitised report: %v", c.file, err)
		}
		for i, f := range fs {
			if again[i].Fingerprint != f.Fingerprint {
				t.Errorf("%s: identity depends on redacted values", c.file)
			}
			loc, _ := LocateImport("import-other-"+c.format, c.format, raw, f.Fingerprint)
			for _, s := range secrets {
				if strings.Contains(string(clean), s) || strings.Contains(f.Title+f.Description, s) || (loc != nil && strings.Contains(string(loc.Raw), s)) {
					t.Errorf("%s: %q kept", c.file, s)
				}
			}
		}
	}
	fa, _ := ParseImport("import-other-falco", "falco", readImportFixture(t, "falco.jsonl"))
	if f := fa[0]; f.Severity != "low" || f.FilePath != "shop/web-7d9f8 (web)" || !strings.Contains(f.Description, "Seen 2 times") || !strings.Contains(f.Description, "T1059") {
		t.Errorf("falco aggregate: %+v", f)
	}
	if fa[1].Severity != "medium" || fa[1].FilePath != "container api" || fa[2].Severity != "critical" || fa[2].FilePath != "host node-2" {
		t.Errorf("falco: %+v", fa[1:])
	}
	te, _ := ParseImport("import-other-tetragon", "tetragon", readImportFixture(t, "tetragon.jsonl"))
	if e := te[0]; e.RuleID != "file-monitoring/security_file_permission" || e.Severity != "medium" || e.Title != "Sensitive file read" ||
		!strings.Contains(e.Description, "/etc/shadow") {
		t.Errorf("tetragon kprobe: %+v", e)
	}
	if te[1].Severity != "high" || te[1].FilePath != "shop/api-55c6 (api)" {
		t.Errorf("tetragon enforced: %+v", te[1])
	}
	tr, _ := ParseImport("import-other-tracee", "tracee", readImportFixture(t, "tracee.jsonl"))
	if tr[0].RuleID != "TRC-102" || tr[0].Severity != "low" || !strings.Contains(tr[0].Description, "T1622") || tr[1].Severity != "high" {
		t.Errorf("tracee: %+v", tr)
	}
	// Neighbouring runtime formats do not take each other's events.
	for doc, want := range map[string]string{
		`{"rule":"r","priority":"Warning","output":"o","output_fields":{},"time":"t"}`:                           "falco",
		`{"process_exec":{"process":{}},"node_name":"n","time":"t"}`:                                             "tetragon",
		`{"timestamp":1,"processName":"p","eventId":"1","eventName":"openat","args":[]}`:                         "tracee",
		`{"rule":{"id":"1","groups":["vulnerability-detector"]},"agent":{"id":"1"},"data":{"vulnerability":{}}}`: "wazuh",
	} {
		if got := DetectImportFormat([]byte(doc)); got != want {
			t.Errorf("%s: detected %q, want %q", doc, got, want)
		}
	}
	// Only exec/exit events or only telemetry: no findings, no error.
	if fs, err := ParseImport("import-other-tetragon", "tetragon", []byte(`{"process_exit":{"process":{}},"node_name":"n","time":"t"}`)); err != nil || len(fs) != 0 {
		t.Errorf("tetragon audit only: %v %d", err, len(fs))
	}
}
